"""Generated by scripts/generate_command_data.py from the live tool registry.

Each preset is one of the 59 CLI wrappers that used to be its own registered
tool. Regenerate rather than hand-edit: the risk_level and requires_admin
fields are the security posture the collapse must preserve exactly.
"""
from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Dict, List, Optional, Union


@dataclass(frozen=True)
class CommandPreset:
    id: str
    summary: str
    env: Union[str, List[str]]
    argv_template: List[str]
    placeholders: List[str]
    risk_level: str
    requires_admin: bool
    probe_binary: str
    example: str
    fallback_preset: Optional[str] = None
    probe_unreliable: bool = False


