def get_preset(preset_id: str) -> Optional[CommandPreset]:
    """Return the preset with this id, or None."""
    return COMMAND_PRESETS.get(preset_id)


def list_presets(env: Optional[str] = None) -> List[CommandPreset]:
    """All presets sorted by id; optionally filtered to one environment."""
    vals = sorted(COMMAND_PRESETS.values(), key=lambda p: p.id)
    if env is None:
        return vals
    out = []
    for p in vals:
        pe = p.env
        if isinstance(pe, list):
            if env in pe:
                out.append(p)
        elif pe == env:
            out.append(p)
    return out


def expand_preset(preset_id: str, args: Dict[str, str]) -> List[str]:
    """Expand a preset to a concrete argv list.

    Security-critical: placeholder values are substituted as argv ELEMENTS
    only. The result is never re-parsed as a shell string and there is no
    free-form flags argument. Raises KeyError naming the first missing
    placeholder (mirrors the old wrapper's 'Missing required tool argument').
    """
    preset = COMMAND_PRESETS.get(preset_id)
    if preset is None:
        raise KeyError(preset_id)
    out: List[str] = []
    for element in preset.argv_template:
        def _repl(m: 're.Match') -> str:
            key = m.group(1)
            if key not in args:
                raise KeyError(key)
            return str(args[key])
        out.append(re.sub(r"\{(\w+)\}", _repl, element))
    return out
